import z from "zod";
import { ai, MODEL } from "../gemini";
import { ACCESS_LABELS, ACCESS_TAGS, parsePreferences } from "../access";
import { getFallbackDares } from "./fallback";
import { DareSchema, DareSetSchema, POINTS } from "./schema";

type PlayerInfo = {
  area?: string | null;
  preferences?: Record<string, unknown> | null;
};

// Prompt generated by Claude
function buildPrompt({ area, preferences }: PlayerInfo) {
  const { needs } = parsePreferences(preferences);
  const needsText =
    needs.length > 0
      ? `The player told us:
${needs.map((n) => `- ${ACCESS_LABELS[n].need} (tag: ${n})`).join("\n")}
Write the main instructions of every dare so they already meet these needs whenever possible.
Every dare must also have at least one alternative tagged with each of these tags: ${needs.join(", ")}.`
      : "The player has not told us about any access needs.";

  return `You write weekly outdoor "dares" for Sea You Outside, an app that gets people outside.

Write exactly 10 dares: 4 "shallows" (about 10 minutes, very easy), 3 "reef" (a short outing),
2 "twilight" (a real outing, around an hour) and 1 "abyss" (the boldest dare of the week).

Rules for every dare:
- Outdoors, in public places only. Plain, friendly language. One or two sentences of instructions.
- At least one alternative that is worth the same and suits different abilities or situations
  (step-free, can be done seated, from a window or balcony, or without nearby water).
  Tag alternatives with every tag that applies, using only: ${ACCESS_TAGS.join(", ")}.
  step-free = wheelchair-friendly, no steps or rough ground; seated-ok = can be done sitting down;
  quiet = calm, low-crowd; near-home = from home, a window, balcony or the immediate street;
  no-water = needs no beach, lake or river; group = good to do with others.
- Never involve heights, climbing, swimming or entering water, being alone at night,
  private property, trespassing, busy roads, or anything risky.
- Some dares can be ocean or water themed (visit any body of water, shoreline cleanup),
  but always give a non-water alternative.
- "proof" describes what one photo should show to prove the dare, e.g. "A photo of litter in a bag".
- Do not include points.

Player's city: ${area || "unknown"}
${needsText}`;
}

export async function generateDares(player: PlayerInfo) {
  try {
    const response = await ai.models.generateContent({
      model: MODEL,
      contents: buildPrompt(player),
      config: {
        responseMimeType: "application/json",
        responseJsonSchema: z.toJSONSchema(z.array(DareSchema)),
      },
    });

    const result = DareSetSchema.safeParse(JSON.parse(response.text ?? ""));
    if (!result.success) {
      console.warn(
        "Gemini dares failed validation, using fallback:",
        result.error.issues,
      );
      return { dares: getFallbackDares(), source: "fallback" as const };
    }

    const dares = result.data.map((d) => ({ ...d, points: POINTS[d.depth] }));
    return { dares, source: "gemini" as const };
  } catch (err) {
    console.warn("Gemini call failed, using fallback:", err);
    return { dares: getFallbackDares(), source: "fallback" as const };
  }
}
